  "source": "def audit(events, at):
    observations = {}
    amendments = {}
    eligible = [event for event in events if event['seen'] <= at]
    for event in eligible:
        if event['kind'] != 'obs':
            continue
        key = event['key']
        rev = event['rev']
        pair = (event['state'], event['stamp'])
        if key not in observations or rev > observations[key][0]:
            observations[key] = (rev, {pair})
        elif rev == observations[key][0]:
            observations[key][1].add(pair)
    for event in eligible:
        if event['kind'] != 'fix':
            continue
        key = event['key']
        if key not in observations or event['rev'] != observations[key][0]:
            continue
        n = event['n']
        pair = (event['state'], event['stamp'])
        if key not in amendments or n > amendments[key][0]:
            amendments[key] = (n, {pair})
        elif n == amendments[key][0]:
            amendments[key][1].add(pair)
    result = {}
    for key, (_, pairs) in observations.items():
        if key in amendments:
            pairs = amendments[key][1]
        if len(pairs) > 1:
            result[key] = 'conflict'
        else:
            state, stamp = next(iter(pairs))
            result[key] = 'stale' if at - stamp > 6 else state
    return result
",
  "result": {
    "alder": "arrived",
    "balsa": "conflict",
    "cedar": "arrived"
  },
  "counterexample": {
    "events": [
      {"kind": "obs", "key": "oak", "rev": 1, "state": "missed", "stamp": 19, "seen": 19},
      {"kind": "fix", "key": "oak", "rev": 1, "n": 1, "state": "arrived", "stamp": 19, "seen": 20}
    ],
    "at": 20,
    "expected": {
      "oak": "arrived"
    }
  }
}
